{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Halve the configured causal context length, rounding up (128 to 64 by default), to reduce stale history and recurrent computation. Existing truncation retains recent interactions in chronological order. Checkpoint metadata already propagates the same context length to the generated predictor.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = max(1, (int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\")) + 1) // 2)"
        }
      ]
    }
  ],
  "change_summary": "Halves context length consistently across training, validation, and prediction while preserving the GRU architecture, readout, loss, optimizer, epoch cap, and all four dataset routes."
}
